using Core.Network.FusionAdapter.Runner;
using Cysharp.Threading.Tasks;
using Fusion;
using UnityEngine;

class Logger : Core.Abstractions.Services.ILogger { public void Error(string f, params object[] a) {} public void Info(string f, params object[] a) {} }
class Mediator : Core.Mediator.Abstractions.IMediator { public UniTask Publish(object n) => new(Task.CompletedTask); }
class Program {
    static int failures;
    static FusionLobbyController New() { GameObject.All.Clear(); NetworkRunner.All.Clear(); return new(new Mediator(), new Logger()); }
    static void Check(bool condition, string message) { if (!condition) throw new Exception(message); }
    static async Task Throws<T>(Task task) where T:Exception { try { await task; } catch (T) { return; } throw new Exception("Expected " + typeof(T).Name); }
    static async Task Run(string name, Func<Task> test) { try { await test(); Console.WriteLine("PASS " + name); } catch (Exception e) { failures++; Console.WriteLine("FAIL " + name + ": " + e.Message); } }
    static async Task Main() {
        await Run("sync exception releases runner", async () => { var c = New(); NetworkRunner.Join = (_, _) => throw new InvalidOperationException(); await Throws<InvalidOperationException>(c.JoinAsync().AsTask()); Check(GameObject.All[0].Destroyed, "runner object retained"); });
        await Run("async exception releases runner", async () => { var c = New(); var t = new TaskCompletionSource<StartGameResult>(); NetworkRunner.Join = (_, _) => t.Task; var join = c.JoinAsync().AsTask(); t.SetException(new InvalidOperationException()); await Throws<InvalidOperationException>(join); Check(GameObject.All[0].Destroyed, "runner object retained"); });
        await Run("cancelled join releases runner", async () => { var c = New(); using var cts = new CancellationTokenSource(); var t = new TaskCompletionSource<StartGameResult>(); NetworkRunner.Join = (_, token) => { token.Register(() => t.TrySetCanceled(token)); return t.Task; }; var join = c.JoinAsync(cancellationToken: cts.Token).AsTask(); cts.Cancel(); await Throws<OperationCanceledException>(join); Check(GameObject.All[0].Destroyed, "runner object retained"); });
        await Run("unsuccessful result releases runner", async () => { var c = New(); NetworkRunner.Join = (_, _) => Task.FromResult(new StartGameResult()); var result = await c.JoinAsync(); Check(!result.IsOk && GameObject.All[0].Destroyed, "unsuccessful runner retained"); });
        await Run("success retains runner and subsequent join reuses lobby", async () => { var c = New(); NetworkRunner.Join = (r, _) => { r.LobbyInfo.IsValid = true; return Task.FromResult(new StartGameResult { Ok = true }); }; Check((await c.JoinAsync()).IsOk, "join failed"); Check((await c.JoinAsync()).IsOk && NetworkRunner.All.Count == 1 && NetworkRunner.All[0].Calls == 1 && !GameObject.All[0].Destroyed, "successful lobby not retained"); });
        await Run("retry after fault uses fresh runner", async () => { var c = New(); NetworkRunner.Join = (_, _) => Task.FromException<StartGameResult>(new InvalidOperationException()); await Throws<InvalidOperationException>(c.JoinAsync().AsTask()); NetworkRunner.Join = (_, _) => Task.FromResult(new StartGameResult { Ok = true }); await c.JoinAsync(); Check(NetworkRunner.All.Count == 2, "retry reused faulted runner"); });
        await Run("parallel failure cannot destroy first lobby", async () => { var c = New(); var pending = new TaskCompletionSource<StartGameResult>(); NetworkRunner.Join = (_, _) => pending.Task; var first = c.JoinAsync().AsTask(); await Throws<InvalidOperationException>(c.JoinAsync().AsTask()); NetworkRunner.All[0].LobbyInfo.IsValid = true; pending.SetResult(new StartGameResult { Ok = true }); Check((await first).IsOk && !GameObject.All[0].Destroyed, "first successful join was interrupted"); });
        await Run("parallel joins do not overlap on one runner", async () => { var c = New(); var pending = new TaskCompletionSource<StartGameResult>(); NetworkRunner.Join = (_, _) => pending.Task; var a = c.JoinAsync().AsTask(); await Throws<InvalidOperationException>(c.JoinAsync().AsTask()); Check(NetworkRunner.All.TrueForAll(r => r.Calls <= 1), "same runner received overlapping JoinSessionLobby calls"); pending.SetResult(new StartGameResult { Ok = false }); await a; });
        await Run("concurrent join rejected without touching first runner", async () => { var c = New(); var pending = new TaskCompletionSource<StartGameResult>(); NetworkRunner.Join = (_, _) => pending.Task; var first = c.JoinAsync().AsTask(); var runner = NetworkRunner.All[0]; runner.LobbyInfo.IsValid = true; await Throws<InvalidOperationException>(c.JoinAsync().AsTask()); await Throws<InvalidOperationException>(c.JoinAsync().AsTask()); Check(NetworkRunner.All.Count == 1 && runner.Calls == 1 && !GameObject.All[0].Destroyed && !first.IsCompleted, "second join touched or interrupted first runner"); pending.SetResult(new StartGameResult { Ok = true }); Check((await first).IsOk && !GameObject.All[0].Destroyed, "first join did not succeed"); Check((await c.JoinAsync()).IsOk && runner.Calls == 1, "guard not released after success or lobby idempotency lost"); });
        await Run("guard releases after join exception", async () => { var c = New(); var original = new InvalidOperationException("original"); NetworkRunner.Join = (_, _) => Task.FromException<StartGameResult>(original); try { await c.JoinAsync(); throw new Exception("expected exception"); } catch (InvalidOperationException e) { Check(ReferenceEquals(original, e), "original exception changed"); } NetworkRunner.Join = (r, _) => { r.LobbyInfo.IsValid = true; return Task.FromResult(new StartGameResult { Ok = true }); }; Check((await c.JoinAsync()).IsOk, "retry after exception rejected"); });
        await Run("guard releases after join cancellation", async () => { var c = New(); using var cts = new CancellationTokenSource(); var pending = new TaskCompletionSource<StartGameResult>(); NetworkRunner.Join = (_, token) => { token.Register(() => pending.TrySetCanceled(token)); return pending.Task; }; var first = c.JoinAsync(cancellationToken: cts.Token).AsTask(); cts.Cancel(); await Throws<OperationCanceledException>(first); NetworkRunner.Join = (r, _) => { r.LobbyInfo.IsValid = true; return Task.FromResult(new StartGameResult { Ok = true }); }; Check((await c.JoinAsync()).IsOk, "retry after cancellation rejected"); });
        await Run("guard releases after unsuccessful result", async () => { var c = New(); NetworkRunner.Join = (_, _) => Task.FromResult(new StartGameResult()); Check(!(await c.JoinAsync()).IsOk, "expected failure result"); NetworkRunner.Join = (r, _) => { r.LobbyInfo.IsValid = true; return Task.FromResult(new StartGameResult { Ok = true }); }; Check((await c.JoinAsync()).IsOk, "retry after failure result rejected"); });
        Console.WriteLine($"Failures: {failures}"); Environment.ExitCode = failures == 0 ? 0 : 1;
    }
}
